CREATE TABLE IF NOT EXISTS planning_periods (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, level text NOT NULL, title text NOT NULL, focus text, starts_at timestamp, ends_at timestamp, progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), reflection text, archived boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS planning_periods_user_level_idx ON planning_periods(user_id, level);
CREATE TABLE IF NOT EXISTS ai_proposals (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, intent text NOT NULL, summary text NOT NULL, reason text NOT NULL, confidence real NOT NULL DEFAULT 0.5, reversible boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'pending', payload jsonb NOT NULL DEFAULT '{}', created_at timestamp NOT NULL DEFAULT now(), decided_at timestamp);
CREATE INDEX IF NOT EXISTS ai_proposals_user_status_idx ON ai_proposals(user_id, status);
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_events_user_created_idx ON audit_events(user_id, created_at);
CREATE TABLE IF NOT EXISTS intelligent_observations (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, category text NOT NULL, title text NOT NULL, evidence text NOT NULL, time_window text NOT NULL, confidence real NOT NULL DEFAULT 0.5, status text NOT NULL DEFAULT 'active', snoozed_until timestamp, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS intelligent_observations_user_status_idx ON intelligent_observations(user_id, status);
CREATE TABLE IF NOT EXISTS beauty_products (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, category text NOT NULL, ingredients text, opened_at timestamp, expires_at timestamp, routine_position text, reaction text, cost_cents integer, repurchase text, usage_frequency text, photo_url text, archived boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS beauty_products_user_idx ON beauty_products(user_id);
CREATE TABLE IF NOT EXISTS hair_logs (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_type text NOT NULL, occurred_at timestamp NOT NULL DEFAULT now(), style text, products text, heat_used boolean NOT NULL DEFAULT false, notes text, next_action text, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS hair_logs_user_occurred_idx ON hair_logs(user_id, occurred_at);
CREATE TABLE IF NOT EXISTS fitness_sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, workout_type text NOT NULL, occurred_at timestamp NOT NULL DEFAULT now(), duration_minutes integer, energy integer CHECK (energy BETWEEN 1 AND 10), soreness integer CHECK (soreness BETWEEN 1 AND 10), equipment text, notes text, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS fitness_sessions_user_occurred_idx ON fitness_sessions(user_id, occurred_at);
CREATE TABLE IF NOT EXISTS closet_items (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, category text NOT NULL, season text, weather_tags text, purchase_date timestamp, purchase_price_cents integer, wear_count integer NOT NULL DEFAULT 0, laundry_state text NOT NULL DEFAULT 'clean', favorite boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'active', image_url text, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS closet_items_user_idx ON closet_items(user_id);
CREATE TABLE IF NOT EXISTS finance_goals (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, goal_type text NOT NULL, target_cents integer NOT NULL, current_cents integer NOT NULL DEFAULT 0, target_date timestamp, notes text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS finance_goals_user_idx ON finance_goals(user_id);
CREATE TABLE IF NOT EXISTS life_timeline_events (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, category text NOT NULL, title text NOT NULL, occurred_at timestamp NOT NULL, summary text, related_entity_type text, related_entity_id text, image_url text, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS life_timeline_events_user_occurred_idx ON life_timeline_events(user_id, occurred_at);
CREATE TABLE IF NOT EXISTS briefing_snapshots (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, period_key text NOT NULL, content jsonb NOT NULL DEFAULT '{}', generated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS briefing_snapshots_user_kind_idx ON briefing_snapshots(user_id, kind);
